+    const saved = process.env.GOOGLE_API_KEY;
+    process.env.GOOGLE_API_KEY = "fixture-not-a-key";
+    try {
+      const r = validateApiKeys(models, { optIn: true, mode: "cli-only" });
+      assert.deepEqual(r.valid.map((v) => v.provider), ["anthropic", "google"]);
